package com.drogaria.backend.controller;
import com.drogaria.backend.dto.*; import com.drogaria.backend.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/favorito") public class FavoritoController { private final FavoritoService service; private final CarrinhoService acesso; public FavoritoController(FavoritoService s,CarrinhoService a){service=s;acesso=a;} @PostMapping public ResponseEntity<FavoritoResponse> adicionar(@Valid @RequestBody FavoritoRequest r,Authentication a){acesso.validarAcesso(r.getIdCliente(),a);return ResponseEntity.status(HttpStatus.CREATED).body(service.adicionar(r));} @GetMapping("/cliente/{id}") public List<FavoritoResponse> listar(@PathVariable Integer id,Authentication a){acesso.validarAcesso(id,a);return service.listar(id);} @DeleteMapping("/{cliente}/{produto}") public ResponseEntity<Void> remover(@PathVariable Integer cliente,@PathVariable Integer produto,Authentication a){acesso.validarAcesso(cliente,a);service.remover(cliente,produto);return ResponseEntity.noContent().build();} }